package io.github.astelev.around_planet.space;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class OrbitalAttitudeTest {
    private final SpaceState state=new SpaceState(new SpaceVector(0,100,0),new SpaceVector(10,0,0));
    @Test void orbitTriadAndOppositeDirections(){var p=OrbitalAttitude.target(OrbitalAttitude.Mode.PROGRADE,state).orElseThrow();var r=OrbitalAttitude.target(OrbitalAttitude.Mode.RADIAL_OUT,state).orElseThrow();var n=OrbitalAttitude.target(OrbitalAttitude.Mode.NORMAL,state).orElseThrow();assertEquals(new SpaceVector(1,0,0),p);assertTrue(new SpaceVector(0,1,0).subtract(r).length()<1e-12);assertEquals(new SpaceVector(0,0,-1),n);assertEquals(0,p.dot(r));assertEquals(p.scale(-1),OrbitalAttitude.target(OrbitalAttitude.Mode.RETROGRADE,state).orElseThrow());assertEquals(r.scale(-1),OrbitalAttitude.target(OrbitalAttitude.Mode.RADIAL_IN,state).orElseThrow());}
    @Test void eccentricRadialDirectionIsPerpendicularToVelocityRatherThanPlanetUp(){var s=new SpaceState(new SpaceVector(0,100,0),new SpaceVector(10,5,0));var radial=OrbitalAttitude.target(OrbitalAttitude.Mode.RADIAL_OUT,s).orElseThrow();assertEquals(0,radial.dot(s.velocity()),1e-10);assertTrue(radial.y()>0 && radial.x()<0);assertNotEquals(radial,OrbitalAttitude.target(OrbitalAttitude.Mode.PLANET_OUT,s).orElseThrow());}
    @Test void zeroSpeedAndRadialCoastHaveNoFalseNormal(){var stopped=new SpaceState(state.position(),SpaceVector.ZERO);assertTrue(OrbitalAttitude.target(OrbitalAttitude.Mode.PROGRADE,stopped).isEmpty());assertTrue(OrbitalAttitude.target(OrbitalAttitude.Mode.NORMAL,stopped).isEmpty());assertTrue(OrbitalAttitude.target(OrbitalAttitude.Mode.PLANET_IN,stopped).isPresent());assertTrue(OrbitalAttitude.target(OrbitalAttitude.Mode.RADIAL_OUT,new SpaceState(state.position(),state.position())).isEmpty());}
    @Test void directionalErrorsAndSaturationMatchControlPorts(){var forward=new SpaceVector(0,0,-1);var right=new SpaceVector(1,0,0);assertEquals(new OrbitalAttitude.Error(0,0),OrbitalAttitude.error(forward,forward,right));assertEquals(90,OrbitalAttitude.error(right,forward,right).yaw());assertEquals(90,OrbitalAttitude.error(new SpaceVector(0,1,0),forward,right).pitch());assertEquals(0,OrbitalAttitude.power(.5,45));assertEquals(15,OrbitalAttitude.power(180,45));assertEquals(8,OrbitalAttitude.power(22.5,45));}
}
